      <button class="settings-row settings-toggle settings-vibration" role="switch" aria-label="Vibration" aria-describedby="vibration-note" aria-checked="true"><span class="settings-icon vibration-symbol">${pn}</span><span class="settings-label">Vibration<small id="vibration-note">On supported devices</small></span><span class="sound-switch" aria-hidden="true"><i></i></span></button>
